<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Loans &amp; Overdue Report</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>@media print{nav,.filters,.no-print{display:none!important}body{background:#fff}.container{max-width:none}}</style></head><body class="bg-light"><main class="container py-4"><nav class="mb-3"><a href="<?= base_url('reports') ?>">Reports</a> / Loans</nav><h1 class="h3">Loans &amp; Overdue Report</h1><form class="row g-2 my-3 filters"><div class="col-auto"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['active'=>'Active','approved'=>'Approved','overdue'=>'Overdue'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($filters['status']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></div><div class="col-auto"><label class="form-label">Branch</label><select class="form-select" name="branch_id"><option value="">All branches</option><?php foreach($branches as $branch): ?><option value="<?= esc($branch['id']) ?>" <?= $filters['branch_id']===(int)$branch['id']?'selected':'' ?>><?= esc($branch['name']) ?></option><?php endforeach ?></select></div><div class="col-auto align-self-end"><button class="btn btn-primary">Filter</button><button type="button" class="btn btn-outline-secondary" onclick="window.print()">Print Report</button></div></form><p><span class="badge text-bg-primary">Total Count: <?= number_format($totalCount) ?></span> <span class="badge text-bg-success">Outstanding Exposure: Rs. <?= number_format($totalAmount,2) ?></span></p><div class="table-responsive bg-white"><table class="table table-striped"><thead><tr><th>Loan Account</th><th>Customer</th><th>Branch</th><th>Status</th><th>Principal (LKR)</th><th>Outstanding (LKR)</th></tr></thead><tbody><?php foreach($loans as $loan): ?><tr><td><?= esc($loan['loan_account_no'] ?? '') ?></td><td><?= esc(trim(($loan['first_name'] ?? '').' '.($loan['last_name'] ?? ''))) ?></td><td><?= esc($loan['branch_name'] ?? '—') ?></td><td><span class="badge text-bg-<?= in_array($loan['status']??'', ['Active','Approved'])?'success':'warning' ?>"><?= esc($loan['status'] ?? '') ?></span></td><td>Rs. <?= number_format((float)($loan['principal_amount'] ?? 0),2) ?></td><td>Rs. <?= number_format((float)($loan['outstanding_balance'] ?? 0),2) ?></td></tr><?php endforeach ?><?php if(!$loans): ?><tr><td colspan="6" class="text-center text-secondary">No loans found.</td></tr><?php endif ?></tbody></table></div></main></body></html>
